	@Override
	KeyTypeName getKeyTypeName() {
		return KeyTypeName.ML_DSA_44;
	}

	@Override
	List<String> getAlgorithms() {
		return Collections.singletonList(JWSAlgorithm.ML_DSA_44);
	}

	@Override
	Object getPrivateKey() {
		return JWK_to_PrivateKey.JWK_to_MLDSA44PrivateKey(jwkPrivate);
	}

	@Override
	Object getPublicKey() {
		return JWK_to_PublicKey.JWK_to_MLDSA44PublicKey(jwkPublic);
	}

	@Test
	public void testPublicKey() throws Exception {
		MLDSAPublicKeyParameters publicKey = JWK_to_PublicKey.JWK_to_MLDSA44PublicKey(jwkPublic);
		byte[] publicKeyBytes = PublicKeyBytes.MLDSA44PublicKey_to_bytes(publicKey);
		assertEquals(1312, publicKeyBytes.length);

		MLDSAPublicKeyParameters publicKey2 = PublicKeyBytes.bytes_to_MLDSA44PublicKey(publicKeyBytes);
		assertArrayEquals(publicKey.getEncoded(), publicKey2.getEncoded());
		JWK jwk2 = PublicKey_to_JWK.MLDSA44PublicKey_to_JWK(publicKey2, null, null);
		assertEquals(jwkPublic, jwk2);
	}

	@Test
	public void testPrivateKey() throws Exception {
		MLDSAPrivateKeyParameters privateKey = JWK_to_PrivateKey.JWK_to_MLDSA44PrivateKey(jwkPrivate);
		byte[] privateKeyBytes = PrivateKeyBytes.MLDSA44PrivateKey_to_bytes(privateKey);
		assertEquals(2560, privateKeyBytes.length);

		MLDSAPrivateKeyParameters privateKey2 = PrivateKeyBytes.bytes_to_MLDSA44PrivateKey(privateKeyBytes);
		assertArrayEquals(privateKey.getEncoded(), privateKey2.getEncoded());
		JWK jwk2 = PrivateKey_to_JWK.MLDSA44PrivateKey_to_JWK(privateKey2, null, null);
		assertEquals(jwkPrivate, jwk2);
	}
